steps.code:
# Fix parsing: handle "and" and trailing period in debtor lists
def parse_expenses_fixed(content):
    expenses = []
    lines = content.strip().split('\n')
    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        # Pattern: - Payer paid $amount for "Description". Owed equally by ...
        m = re.match(r'^- (\w+) paid \$([\d.]+) for "([^"]+)"\. Owed equally by (.+)$', line)
        if m:
            payer = m.group(1)
            amount = float(m.group(2))
            description = m.group(3)
            debtors_str = m.group(4).strip()
            # Remove trailing period
            if debtors_str.endswith('.'):
                debtors_str = debtors_str[:-1]
            # Split on commas, then handle "and" in the last part
            parts = [p.strip() for p in debtors_str.split(',')]
            debtors = []
            for p in parts:
                if ' and ' in p:
                    sub = p.split(' and ')
                    debtors.extend([s.strip() for s in sub])
                else:
                    debtors.append(p)
            expenses.append({
                'payer': payer,
                'amount': amount,
                'description': description,
                'debtors': debtors
            })
        else:
            print(f"Could not parse line: {line}")
    return expenses

# Re-parse all notes
parsed_expenses = {}
for note_id, content in trip_notes.items():
    parsed_expenses[note_id] = parse_expenses_fixed(content)
    print(f"Note {note_id}: {len(parsed_expenses[note_id])} expenses parsed")

# Print for verification
for note_id, expenses in parsed_expenses.items():
    print(f"Note {note_id}:")
    for exp in expenses:
        print(f"  {exp['payer']} paid ${exp['amount']} for '{exp['description']}' owed by {exp['debtors']}")

